// test_rustc_12k_decls.rs - Test suite expecting 12k rustc declarations
// Generated by step4_bootstrap - Rustc 12k Declarations

use split_decls_genesis::{
    mkrustc_full_split, mkdep_split_decls, mkfull_dep_tree, mkdeps_paths,
    extract_all_declarations_from_dependency, get_rustc_dependencies, 
    extract_cargo_dependencies, find_rust_files_in_dependency
};

fn main() -> anyhow::Result<()> {
    println!("🧬 Testing rustc 12k declarations extraction...");
    
    // First check what paths we're actually finding
    let rustc_deps = get_rustc_dependencies()?;
    println!("\n📦 Rustc dependencies to process:");
    for dep in &rustc_deps {
        let rust_files = find_rust_files_in_dependency(&dep.path);
        println!("  {} → {} ({} files)", dep.name, dep.path, rust_files.len());
        
        if rust_files.len() > 0 {
            println!("    Sample files:");
            for file in rust_files.iter().take(3) {
                println!("      📄 {}", file.display());
            }
        }
    }
    
    // Extract all declarations
    println!("\n🦀 Extracting all rustc declarations:");
    let rustc_decls = mkrustc_full_split!();
    
    println!("\n📊 RUSTC DECLARATIONS RESULTS:");
    println!("  🎯 Target: 12,000 declarations");
    println!("  🔧 Found: {} declarations", rustc_decls.len());
    println!("  📈 Progress: {:.1}% of target", (rustc_decls.len() as f64 / 12000.0) * 100.0);
    
    if rustc_decls.len() >= 12000 {
        println!("  🎉 SUCCESS: Target achieved!");
    } else if rustc_decls.len() >= 1000 {
        println!("  ⚡ GOOD: Substantial declarations found");
    } else {
        println!("  ⚠️  Need to expand search paths");
    }
    
    // Show sample declarations
    if !rustc_decls.is_empty() {
        println!("\n📝 Sample declarations:");
        for (i, decl) in rustc_decls.iter().take(10).enumerate() {
            println!("    {}. {}", i+1, decl);
        }
    }
    
    // Count declaration types
    let mut type_counts = std::collections::HashMap::new();
    for decl in &rustc_decls {
        if let Some(decl_type) = decl.split('!').next() {
            *type_counts.entry(decl_type).or_insert(0) += 1;
        }
    }
    
    println!("\n📈 Declaration types breakdown:");
    for (decl_type, count) in type_counts {
        println!("  {} {}: {}", 
                 match decl_type {
                     "mkdeclfn" => "🔧",
                     "mkdeclstruct" => "🏗️",
                     "mkdeclenum" => "📋",
                     "mkdecltrait" => "🎯",
                     "mkdeclimpl" => "⚙️",
                     _ => "📦"
                 },
                 decl_type, count);
    }
    
    println!("\n🎉 Rustc 12k declarations test complete!");
    Ok(())
}
